#include <iostream>
#include <future>
#include <thread>

int compute() { return 120 + 3; }

int main() {
    std::packaged_task<int()> task(compute);
    std::future<int> f = task.get_future();
    std::thread t(std::move(task));   // packaged_task 可移动进线程
    t.join();
    std::cout << "result=" << f.get();   // 经 future 取任务返回值
}
